import { sys } from 'cc';
import type { StoryEffect } from './StoryMapTypes';

const STORAGE_PREFIX = 'story_mvp_state_v1';

export interface StoryPersistBlob {
    accepted: number[];
    completed: number[];
    completedEvents: string[];
}

/**
 * 本地剧情进度（任务接取/完成、已完成事件 ID）。
 * 将来应由服务器权威存档接管；当前仅用于 MVP 跑通主线。
 */
export class StoryLocalTaskState {
    private readonly _accepted = new Set<number>();
    private readonly _completed = new Set<number>();
    private readonly _completedEvents = new Set<string>();

    constructor(
        readonly mapCode: string,
        readonly persistToStorage: boolean
    ) {
        if (this.persistToStorage) this.load();
    }

    storageKey(): string {
        return `${STORAGE_PREFIX}_${this.mapCode}`;
    }

    isTaskAccepted(taskId: number): boolean {
        return this._accepted.has(taskId);
    }

    isTaskCompleted(taskId: number): boolean {
        return this._completed.has(taskId);
    }

    isEventCompleted(eventId: string): boolean {
        return this._completedEvents.has(eventId);
    }

    acceptTask(taskId: number): void {
        this._accepted.add(taskId);
        this.save();
    }

    completeTask(taskId: number): void {
        this._completed.add(taskId);
        this._accepted.delete(taskId);
        this.save();
    }

    markEventCompleted(eventId: string): void {
        this._completedEvents.add(eventId);
        this.save();
    }

    /** MVP：按 Json 的 server.effects 应用本地任务变更（不含 teleport 真实跳转）。 */
    applyServerEffects(effects: StoryEffect[]): void {
        if (!effects?.length) return;
        for (let i = 0; i < effects.length; i++) {
            const e = effects[i];
            if (e.action === 'task_accept' && e.taskId !== undefined) {
                this.acceptTask(e.taskId);
            } else if (e.action === 'task_submit' && e.taskId !== undefined) {
                this.completeTask(e.taskId);
            }
        }
    }

    load(): void {
        if (!sys.localStorage) return;
        const raw = sys.localStorage.getItem(this.storageKey());
        if (!raw) return;
        try {
            const blob = JSON.parse(raw) as StoryPersistBlob;
            this._accepted.clear();
            this._completed.clear();
            this._completedEvents.clear();
            (blob.accepted ?? []).forEach((id) => this._accepted.add(id));
            (blob.completed ?? []).forEach((id) => this._completed.add(id));
            (blob.completedEvents ?? []).forEach((id) => this._completedEvents.add(id));
        } catch {
            // ignore corrupt storage
        }
    }

    save(): void {
        if (!this.persistToStorage || !sys.localStorage) return;
        const blob: StoryPersistBlob = {
            accepted: [...this._accepted],
            completed: [...this._completed],
            completedEvents: [...this._completedEvents],
        };
        sys.localStorage.setItem(this.storageKey(), JSON.stringify(blob));
    }

    resetProgress(): void {
        this._accepted.clear();
        this._completed.clear();
        this._completedEvents.clear();
        if (sys.localStorage) sys.localStorage.removeItem(this.storageKey());
    }
}
